reference_solution:
def zigzag_grid_traversal_with_skip(grid):
    answer=[]
    take=True
    for row_index,row in enumerate(grid):
        values=row if row_index%2==0 else reversed(row)
        for value in values:
            if take:answer.append(value)
            take=not take
    return answer

